/*
 * A210212  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A210211; see the Formula section.
 * https://oeis.org/A210212
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = the nth coefficient of the polynomial v(n,x) generated by
 *            u(1,x)=1, v(1,x)=1 u(n,x)=x*u(n-1,x)+v(n-1,x)+1
 *            v(n,x)=u(n-1,x)+2x*v(n-1,x)+1 The sequence enumerates the
 *            coefficients of v(n,x) row by row (row 1 has coefficient 1; row
 *            2 has 2,2; row 3 has 3,5,4; …)
 * Range:     u8 n <= 31, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Return the nth term of A210212 (n ≥ 1). */
seq_t a(idx_t n)
{
    if (n < 1) return 0;          /* undefined for n=0, return 0 safely */

    /* Find the row r such that r*(r+1)/2 >= n and (r-1)*r/2 < n. */
    idx_t low = 1, high = 1;
    while ((unsigned __int128)high * (high + 1) / 2 < n) high <<= 1;
    while (low < high) {
        idx_t mid = low + ((high - low) >> 1);
        if ((unsigned __int128)mid * (mid + 1) / 2 >= n)
            high = mid;
        else
            low = mid + 1;
    }
    idx_t r = low;                /* row number (1‑based) */

    if (r == 1) return (seq_t)1;   /* v(1,x)=1 */

    /* Allocate arrays for the previous row. */
    seq_t *prev_u = (seq_t *)malloc(sizeof(seq_t));
    seq_t *prev_v = (seq_t *)malloc(sizeof(seq_t));
    prev_u[0] = (seq_t)1;
    prev_v[0] = (seq_t)1;

    /* Build rows up to row r. */
    for (idx_t cur = 2; cur <= r; ++cur) {
        size_t len    = (size_t)cur;          /* number of coefficients in this row */
        seq_t *cur_u  = (seq_t *)malloc(sizeof(seq_t) * len);
        seq_t *cur_v  = (seq_t *)malloc(sizeof(seq_t) * len);

        /* v(cur,x) = u(prev,x) + 2x*v(prev,x) + 1   */
        cur_v[0] = prev_u[0] + (seq_t)1;        /* constant term */
        for (size_t k = 1; k < len; ++k) {
            seq_t up_k   = (k < len - 1) ? prev_u[k] : (seq_t)0; /* u(prev,k) or 0 */
            seq_t vp_km1 = prev_v[k - 1];                       /* v(prev,k-1) */
            cur_v[k] = up_k + (seq_t)2 * vp_km1;
        }

        /* u(cur,x) = x*u(prev,x) + v(prev,x) + 1   */
        cur_u[0] = prev_v[0] + (seq_t)1;        /* constant term */
        for (size_t k = 1; k < len; ++k) {
            seq_t up_km1 = prev_u[k - 1];                          /* u(prev,k-1) */
            seq_t vp_k   = (k < len - 1) ? prev_v[k] : (seq_t)0; /* v(prev,k) or 0 */
            cur_u[k] = up_km1 + vp_k;
        }

        /* Free the previous row and advance. */
        free(prev_u);
        free(prev_v);
        prev_u = cur_u;
        prev_v = cur_v;
    }

    /* Compute column (0‑based) within row r. */
    idx_t start_of_row = ( (unsigned __int128)(r - 1) * r ) / 2;   /* 0‑based index of first element of row r */
    idx_t col = n - start_of_row - 1;                            /* 0‑based column */

    seq_t result = prev_v[(size_t)col];

    /* Free the last allocated row. */
    free(prev_u);
    free(prev_v);

    return result;
}
